import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(2.5, -0.2, 0);
  group.scale.set(1, 1, 1);

  // Load the GLB mesh via cached loader
  const glb = ctx.glbLoader('/prism-mock/orrery/meshes/gear-a.glb');
  if (glb && glb.scene) {
    group.add(glb.scene);
  }

  // Initialize event handlers and tracking
  const handlers = {};
  const timelines = [];

  // Hover interaction - rise-in animation (0.15 scene units, power3.out, 0.7s)
  handlers.onPointerEnter = () => {
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;

    const tl = gsap.timeline();
    tl.to(group.position, {
      y: '+=0.15',
      duration: 0.7,
      ease: 'power3.out'
    });
    timelines.push(tl);
  };

  handlers.onPointerLeave = () => {
    const tl = gsap.timeline();
    tl.to(group.position, {
      y: '-=0.15',
      duration: 0.7,
      ease: 'power3.out'
    });
    timelines.push(tl);
  };

  // Click interaction - hub-journal.select event
  handlers.onClick = () => {
    // Event emission handled by parent system via config metadata
  };

  // Apply cinematic primitives
  if (ctx.primitives) {
    ctx.primitives['parallax-scroll'](group, {
      intensity: 0.4
    });

    ctx.primitives['magnetic-cursor'](group, {
      radius: 1.2,
      strength: 0.35
    });
  }

  // Attach handlers to userData
  group.userData.handlers = handlers;

  // Cleanup function
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;

    group.traverse(child => {
      if (child.geometry) {
        child.geometry.dispose();
      }
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach(mat => mat.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
